package jp.wakeguard.alarm;import android.content.*;import android.os.Build;import java.time.LocalDate;public class SnoozeReceiver extends BroadcastReceiver{@Override public void onReceive(Context c,Intent i){long id=i==null?-1:i.getLongExtra("alarmId",-1),at=i==null?-1:i.getLongExtra("expectedAt",-1);if(id<0||at<=0||!SnoozeScheduler.consumeIfExpected(c,id,at))return;if(id>=1000&&AlarmStore.find(c,id)==null)return;Intent s=new Intent(c,AlarmService.class).setAction(AlarmService.ACTION_FIRE_NEW).putExtra(AlarmService.EXTRA_ALARM_ID,id).putExtra(AlarmService.EXTRA_EPOCH_DAY,LocalDate.now().toEpochDay()).putExtra(AlarmService.EXTRA_EXPECTED_AT,at);try{if(Build.VERSION.SDK_INT>=26)c.startForegroundService(s);else c.startService(s);}catch(Throwable ignored){}}}
